def Target : Prop :=
  ∀ (X1 : Type u) (X2 : Type v) (E : Type w), Nonempty E → ∀ (g : X1 → X2) (c2 : X1 → E),
    ((∃ c4 : X2 → E, ∀ s, c2 s = c4 (g s)) ↔ (∀ s s', g s = g s' → c2 s = c2 s'))

